import {escapeHTML as e} from '/model.mjs';
const app=document.querySelector('#tickets');let catalog=[],requestId=crypto.randomUUID(),sending=false,widget;
const demoRequested=new URLSearchParams(location.search).get('demo')==='1';
const money=pence=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(pence/100);
async function start(){
  const response=await fetch('/api/ticket/catalog'+(demoRequested?'?demo=1':''),{cache:'no-store'}),data=await response.json();
  if(!response.ok){if(response.status===401&&demoRequested){app.innerHTML='<h1>Try the ticket demo.</h1><section class="panel"><h2>Stripe sandbox · No real payment</h2><p>Sign in with the owner account and authenticator to demonstrate checkout, ticket email and scanning. No real ticket or payment will be issued.</p><a class="button" href="/door/?next=demo">Sign in to start the demo</a></section>';return;}throw Error(data.error||'Bookings are unavailable.');}if(demoRequested&&data.testMode!==true)throw Error('This demo requires Stripe test mode. Live payments are blocked.');catalog=data.categories;
  if(!catalog.length){app.innerHTML='<h1>Fight night is coming.</h1><section class="panel"><p>Online QR tickets are not on sale yet. Check the event page for the organiser’s current booking information.</p><a class="button" href="/events/">View event information</a></section>';return;}
  app.innerHTML=`<h1>Your seat at ringside.</h1><p>One named attendee. One unique QR. Tickets arrive by email and can be printed or shown on your phone.</p><section class="panel"><form id="booking"><label class="field">Ticket category<select name="category">${catalog.map(c=>`<option value="${e(c.id)}" ${c.available<1?'disabled':''}>${e(c.event)} · ${e(c.name)} · ${e(money(c.pricePence))}${c.available<1?' · Sold out':''}</option>`).join('')}</select></label><p id="event-info"></p><div id="booking-terms"></div><label class="field">Number of tickets<select name="quantity">${Array.from({length:8},(_,i)=>`<option>${i+1}</option>`).join('')}</select></label><label class="field">Booking email<input name="email" type="email" autocomplete="email" maxlength="254" required></label><div id="attendees"></div><p id="total"></p><label class="check"><input name="id-agreement" type="checkbox" required>I have read the event refund and transfer terms above. I understand each attendee must bring ID matching the name on their ticket. Tickets are digital and will be checked at the door.</label><p><small>We use your email to deliver your tickets and important booking updates. Marketing subscriptions will be offered separately once activated.</small></p><button id="checkout">Continue to secure payment</button><p id="message" class="message" role="status"></p></form></section>`;
  if(data.testMode){app.insertAdjacentHTML('afterbegin','<section class="panel" role="status"><h2>Sandbox test booking</h2><p>Only the signed-in owner can use this test checkout. No real payment is taken. Use test attendee details. Test card: 4242 4242 4242 4242, a future expiry and any three-digit CVC. Never use a real card.</p></section>');document.querySelector('#checkout').textContent='Continue to test payment';}
  const form=document.querySelector('#booking');form.oninput=()=>{requestId=crypto.randomUUID();};form.elements.quantity.onchange=attendees;form.elements.category.onchange=update;form.onsubmit=checkout;attendees();
  const challenge=document.createElement('div');challenge.id='challenge';form.insertBefore(challenge,document.querySelector('#checkout'));
  if(data.challengeKey){const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=()=>{widget=window.turnstile.render('#challenge',{sitekey:data.challengeKey,action:'booking',theme:'dark'});};document.head.append(script);}
}
function attendees(){const form=document.querySelector('#booking'),target=document.querySelector('#attendees'),previous=[...target.querySelectorAll('input')].map(input=>input.value);target.innerHTML=Array.from({length:Number(form.elements.quantity.value)},(_,i)=>`<label class="field">Attendee ${i+1} · full name as shown on ID<input name="attendee" value="${e(previous[i]||'')}" minlength="2" maxlength="100" autocomplete="off" required></label>`).join('');update();}
function update(){const form=document.querySelector('#booking'),category=catalog.find(c=>c.id===form.elements.category.value);if(!category)return;document.querySelector('#event-info').textContent=`${category.venue} · ${new Date(category.startsAt).toLocaleString('en-GB',{dateStyle:'long',timeStyle:'short',timeZone:'Europe/London'})}`;document.querySelector('#booking-terms').innerHTML=(category.fighterStatus==='withdrawn'?'<h3>Fighter withdrawal · event going ahead</h3><p>'+e(category.fighterNotice)+'</p><p>'+e(category.fighterChangePolicy)+'</p>':'')+'<h3>Refunds & cancellations</h3><p>'+e(category.refundPolicy||'Contact the organiser for this event’s booking terms before paying.')+'</p><h3>Transfers</h3><p>'+e(category.transferPolicy||'Transfers require organiser confirmation.')+'</p>';document.querySelector('#total').textContent='Total '+money(category.pricePence*Number(form.elements.quantity.value));document.querySelector('#checkout').disabled=category.available<Number(form.elements.quantity.value);}
async function checkout(event){event.preventDefault();if(sending)return;sending=true;const form=event.target,button=document.querySelector('#checkout');button.disabled=true;const fields=Object.fromEntries(new FormData(form));try{
  const response=await fetch('/api/ticket/checkout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({demo:demoRequested,requestId,category:fields.category,revision:catalog.find(c=>c.id===fields.category)?.revision,email:fields.email,challenge:fields['cf-turnstile-response']||'',attendees:[...form.querySelectorAll('[name="attendee"]')].map(input=>input.value) }),signal:AbortSignal.timeout(45000)}),data=await response.json();if(!response.ok)throw Error(data.error||'Checkout is unavailable.');location.assign(data.url);
}catch(error){document.querySelector('#message').textContent=error.message||'Connection lost. Try this booking again.';button.disabled=false;if(widget!==undefined)window.turnstile.reset(widget);}finally{sending=false;}}
start().catch(error=>{app.innerHTML=`<h1>Book your fight night.</h1><section class="panel"><p>${e(error.message)}</p><a class="button" href="/events/">Current booking information</a></section>`;});
